package floydwarshall;

import floydwarshall.algorithm.AllPairsShortestPaths;
import floydwarshall.algorithm.FloydWarshallSolver;
import floydwarshall.algorithm.VertexPath;
import floydwarshall.demo.ExampleGraphs;
import floydwarshall.graph.WeightedGraph;
import floydwarshall.weight.DoubleWeightSystem;
import floydwarshall.weight.IntWeightSystem;
import floydwarshall.weight.LongWeightSystem;

import java.util.List;
import java.util.Optional;

/**
 * Dependency-free test suite for the Floyd-Warshall library. Run via
 * {@code java floydwarshall.FloydWarshallTest}; exits non-zero on failure.
 */
public final class FloydWarshallTest {

    public static void main(String[] args) {
        TestAssertions a = new TestAssertions();
        int failures = 0;
        failures += run("classic distances match baseline", () -> classicDistances(a));
        failures += run("path reconstruction", () -> pathReconstruction(a));
        failures += run("unreachable vertex", () -> unreachable(a));
        failures += run("negative cycle detection", () -> negativeCycle(a));
        failures += run("double weights", () -> doubleWeights(a));
        failures += run("long weights", () -> longWeights(a));

        System.out.println();
        System.out.println(a.checks() + " checks executed.");
        if (failures > 0) {
            System.out.println(failures + " test(s) FAILED.");
            System.exit(1);
        }
        System.out.println("All tests passed.");
    }

    private static int run(String name, Runnable test) {
        try {
            test.run();
            System.out.println("[PASS] " + name);
            return 0;
        } catch (Throwable t) {
            System.out.println("[FAIL] " + name + ": " + t.getMessage());
            return 1;
        }
    }

    private static FloydWarshallSolver<Integer> intSolver() {
        return new FloydWarshallSolver<>(new IntWeightSystem());
    }

    private static void classicDistances(TestAssertions a) {
        AllPairsShortestPaths<Integer> r = intSolver().solve(ExampleGraphs.classicFiveVertex());
        int[][] expected = {
                {0, 4, 5, 5, 7},
                {3, 0, 1, 4, 6},
                {2, 6, 0, 3, 5},
                {3, 7, 1, 0, 2},
                {1, 5, 5, 4, 0},
        };
        for (int i = 0; i < expected.length; i++) {
            for (int j = 0; j < expected.length; j++) {
                a.assertEquals(expected[i][j], r.distance(i, j).orElseThrow(),
                        "distance(" + i + "," + j + ")");
            }
        }
    }

    private static void pathReconstruction(TestAssertions a) {
        AllPairsShortestPaths<Integer> r = intSolver().solve(ExampleGraphs.classicFiveVertex());
        Optional<VertexPath<Integer>> path = r.path(1, 0);
        a.assertTrue(path.isPresent(), "path 1->0 should exist");
        a.assertEquals(List.of(1, 2, 0), path.get().vertices(), "path 1->0 vertices");
        a.assertEquals(3, path.get().totalCost(), "path 1->0 cost");
        a.assertEquals(0, r.path(2, 2).orElseThrow().totalCost(), "self path cost");
    }

    private static void unreachable(TestAssertions a) {
        WeightedGraph<Integer> g = WeightedGraph.<Integer>builder(3).addEdge(0, 1, 1).build();
        AllPairsShortestPaths<Integer> r = intSolver().solve(g);
        a.assertTrue(r.distance(0, 2).isEmpty(), "vertex 2 unreachable");
        a.assertTrue(r.path(0, 2).isEmpty(), "no path to vertex 2");
        a.assertEquals(1, r.distance(0, 1).orElseThrow(), "0->1 reachable");
    }

    private static void negativeCycle(TestAssertions a) {
        WeightedGraph<Integer> cyclic = WeightedGraph.<Integer>builder(2)
                .addEdge(0, 1, 1)
                .addEdge(1, 0, -2)
                .build();
        a.assertTrue(intSolver().solve(cyclic).hasNegativeCycle(),
                "negative cycle should be detected");

        WeightedGraph<Integer> acyclic = WeightedGraph.<Integer>builder(2).addEdge(0, 1, 5).build();
        a.assertTrue(!intSolver().solve(acyclic).hasNegativeCycle(),
                "no false-positive negative cycle");
    }

    private static void doubleWeights(TestAssertions a) {
        WeightedGraph<Double> g = WeightedGraph.<Double>builder(3)
                .addEdge(0, 1, 1.5)
                .addEdge(1, 2, 2.25)
                .addEdge(0, 2, 5.0)   // direct edge is more expensive than 0->1->2
                .build();
        AllPairsShortestPaths<Double> r = new FloydWarshallSolver<>(new DoubleWeightSystem()).solve(g);
        a.assertEquals(Double.valueOf(3.75), r.distance(0, 2).orElseThrow(), "0->2 cheapest cost");
        a.assertEquals(List.of(0, 1, 2), r.path(0, 2).orElseThrow().vertices(), "0->2 path");
    }

    private static void longWeights(TestAssertions a) {
        long big = 3_000_000_000L; // beyond int range
        WeightedGraph<Long> g = WeightedGraph.<Long>builder(3)
                .addEdge(0, 1, big)
                .addEdge(1, 2, big)
                .build();
        AllPairsShortestPaths<Long> r = new FloydWarshallSolver<>(new LongWeightSystem()).solve(g);
        a.assertEquals(Long.valueOf(2 * big), r.distance(0, 2).orElseThrow(), "0->2 sums without overflow");
    }
}

